# media_data.py - byte-exact regeneration of the upstream test media
# fixtures (src/media/*). These files are binary and therefore cannot
# be committed to git: the CI checkout-pr step applies the GitCode
# PR .diff via `git apply`, and GitCode's .diff endpoint does not
# carry the base85 'GIT binary patch' payload (it emits only 'Binary
# files differ'), so `git apply` fails with 'missing binary patch data'.
# Regenerating the identical bytes at source() time keeps the vendored
# tree byte-for-byte faithful to the official 3.9.14 release (sha256
# 4ad60d94...) while keeping the PR diff pure text.
#
# Each dict maps the media filename (relative to src/media/) to its
# base64 payload. test.mp3 == another-test.mp3 (identical upstream bytes).
